"use client";

import { useRef, type ReactNode } from "react";
import { motion, useReducedMotion, useScroll, useSpring, useTransform } from "framer-motion";

/**
 * A product window framed like a picture: laid on the painted sky
 * (public/landing/painting.webp, generated by scripts/painting), after Rankaria's
 * dashboard on a Van Gogh. Used by the homepage showcase and every feature page's.
 *
 * Motion is tied to the scroll, through a spring so it never jitters: the window
 * rises and tips upright as it comes up the screen, and the painting drifts the other
 * way behind it. With reduced motion the window simply sits flat. Place it inside a
 * `Band inner="overflow-hidden"`.
 */
export function PaintedStage({ children }: { children: ReactNode }) {
  const ref = useRef<HTMLDivElement>(null);
  const reduce = useReducedMotion();

  // The rise: from the stage's top entering the screen to it reaching the upper
  // fifth, so the window is flat by the time it's read.
  const { scrollYProgress: rise } = useScroll({ target: ref, offset: ["start end", "start 0.2"] });
  const p = useSpring(rise, { stiffness: 120, damping: 28, mass: 0.6 });
  const rotateX = useTransform(p, [0, 1], [14, 0]);
  const scale = useTransform(p, [0, 1], [0.93, 1]);
  const y = useTransform(p, [0, 1], [64, 0]);

  // The painting's drift, over the whole time the stage is on screen.
  const { scrollYProgress: pass } = useScroll({ target: ref, offset: ["start end", "end start"] });
  const bgY = useTransform(pass, [0, 1], ["-7%", "7%"]);

  return (
    <div
      ref={ref}
      className="relative bg-[#1563d6] px-3 pb-14 pt-12 [perspective:1800px] sm:px-10 sm:pb-20 sm:pt-16 lg:px-16"
    >
      {/* A plain img, not next/image: a decorative backdrop moved by a motion
          value, where next/image's wrapper would fight the transform. */}
      <motion.img
        src="/landing/painting.webp"
        alt=""
        aria-hidden
        width={2200}
        height={1400}
        loading="lazy"
        decoding="async"
        draggable={false}
        className="pointer-events-none absolute inset-0 h-full w-full scale-[1.16] select-none object-cover"
        style={reduce ? undefined : { y: bgY }}
      />
      <motion.div
        className="relative mx-auto max-w-5xl will-change-transform"
        style={reduce ? undefined : { rotateX, scale, y, transformOrigin: "50% 0%" }}
      >
        {children}
      </motion.div>
    </div>
  );
}
